// AgentFace (#3335) — the org-chart agent-node face card: name, role chip, and a 4-line-clamped
// blurb. Promoted from harvested (it was already complete and tested) into base-studio-code, refactored
// to use the real Box/Row/Text/Chip primitives instead of local raw-div redeclarations. The blurb clamp
// is CSS (a 4-line `-webkit-box`) so a persona blurb of any length can never grow the fixed node box —
// the full text stays in the DOM (the truncation is purely visual), verified together with TeamsCanvas.
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";

export interface PositionDisplay {
  glyph: string;
  name: string;
  role?: string;
  blurb: string;
  dept?: string;
}

const DEMO_POSITION: PositionDisplay = { glyph: "◆", name: "builder-1", role: "engineer", blurb: "Implements features end to end, from the plan to a merged PR." };

export function AgentFace({ d = DEMO_POSITION, isSel = false }: { d?: PositionDisplay; isSel?: boolean }) {
  return (
    <Box style={{
      width: "100%", height: "100%", boxSizing: "border-box", padding: "10px 12px",
      display: "flex", flexDirection: "column", gap: 8, borderRadius: 13, background: "var(--bg-elev)",
      border: `1px solid ${isSel ? "var(--accent)" : "var(--border)"}`,
      boxShadow: isSel ? "0 0 0 4px color-mix(in oklch, var(--accent) 18%, transparent)" : "0 3px 12px rgba(0,0,0,.3)",
    }}>
      <Row gap={9} align="start">
        <Box style={{
          width: 27, height: 27, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 13, color: isSel ? "#fff" : "var(--accent)",
          background: isSel ? "var(--accent)" : "color-mix(in oklch, var(--accent) 14%, transparent)", flex: "none",
        }}>{d.glyph}</Box>
        <Box style={{ minWidth: 0, flex: 1 }}>
          <Row gap={6} align="center">
            <Text as="span" weight={600} size={13.5} style={{ lineHeight: 1.15, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{d.name}</Text>
            {d.role && <Chip color="var(--accent)" style={{ flex: "none" }}>{d.role}</Chip>}
          </Row>
          <Text as="div" size={10.5} tone="muted" style={{
            lineHeight: 1.3, marginTop: 2,
            display: "-webkit-box", WebkitLineClamp: 4, WebkitBoxOrient: "vertical", overflow: "hidden",
          }}>{d.blurb}</Text>
        </Box>
      </Row>
    </Box>
  );
}
